param([string]$OutFile='evidence/issue-141/authority-surface-audit.json',[string]$GeneratedAt='',[string]$TemplatesRoot='templates')
$ErrorActionPreference='Stop';$root=(Resolve-Path (Join-Path $PSScriptRoot '..\..')).Path;Set-Location $root;$base=(git -C $root rev-parse HEAD).Trim();$unparseable=@();$permissions=@();$surfaces=@();$protected=@()
function Add-ProtectedFile([string]$Path){$full=(Resolve-Path $Path).Path;$rel=$full.Substring($root.Length+1).Replace('\','/');if(-not ($script:protected|Where-Object path -eq $rel)){$script:protected += [pscustomobject]@{path=$rel;sha256=(Get-FileHash $full -Algorithm SHA256).Hash}}}
# OpenCode templates are parsed as JSON, not scanned as text.
$templateFiles=@((Join-Path $TemplatesRoot 'opencode.v1.json.tmpl'),(Join-Path $TemplatesRoot 'opencode.v2.json.tmpl'))
foreach($p in $templateFiles){$logical=$p.Replace('\','/');try{$j=Get-Content $p -Raw|ConvertFrom-Json;Add-ProtectedFile $p;if($logical -like '*v1*'){$agents=$j.agent;foreach($a in $agents.PSObject.Properties){$perm=$a.Value.permission;if($perm){foreach($k in $perm.PSObject.Properties){$permissions += [pscustomobject]@{token=$k.Name;surface='opencode';path=$logical;declared_by="$logical agent.$($a.Name).permission.$($k.Name)";enforced_by=$null;enforcement_kind='advisory';value=$k.Value}}};if($a.Name -eq 'build' -and $j.subagent_depth -ne $null){$permissions += [pscustomobject]@{token='subagent_depth';surface='opencode';path=$logical;declared_by="$logical subagent_depth";enforced_by=$null;enforcement_kind='advisory';value=$j.subagent_depth}}}}else{foreach($a in $j.agents.PSObject.Properties){foreach($rule in $a.Value.permissions){$token=[string]$rule.action+':'+[string]$rule.resource;$permissions += [pscustomobject]@{token=$token;surface='opencode';path=$logical;declared_by="$logical agents.$($a.Name).permissions[]";enforced_by=$null;enforcement_kind='advisory';value=$rule.effect}}};$permissions += [pscustomobject]@{token='subagent_depth';surface='opencode';path=$logical;declared_by="$logical experimental.subagent_depth";enforced_by=$null;enforcement_kind='advisory';value=$j.experimental.subagent_depth}}}catch{$unparseable += [pscustomobject]@{path=$logical;reason=$_.Exception.Message;classification='UNPARSEABLE'}}}
# Agent declarations use the repository's YAML parser and canonical schema.
. scripts/runtime/lib/AgentTranslator.ps1
$agentFiles=Get-ChildItem source/agents -Filter '*.md' -File
foreach($f in $agentFiles){$rel=$f.FullName.Substring($root.Length+1).Replace('\','/');try{$split=Split-AgentFileText -RawText (Get-Content $f.FullName -Raw) -SourceName $f.BaseName;$canon=Convert-AgentFrontmatterYamlToCanonical -FrontmatterText $split.FrontmatterText -SourceName $f.BaseName;Add-ProtectedFile $rel;if($canon.EditPresent){$permissions += [pscustomobject]@{token='edit';surface='opencode';path=$rel;declared_by="$rel permission.edit";enforced_by=$null;enforcement_kind='advisory';value=$canon.Edit}};if($canon.BashKind -ne 'absent'){$permissions += [pscustomobject]@{token='bash';surface='opencode';path=$rel;declared_by="$rel permission.bash";enforced_by=$null;enforcement_kind='advisory';value=$canon.BashKind}};foreach($x in $canon.ExtraPermissions){$permissions += [pscustomobject]@{token=$x.Name;surface='opencode';path=$rel;declared_by="$rel permission.$($x.Name)";enforced_by=$null;enforcement_kind='advisory';value=$x.Effect}}}catch{$unparseable += [pscustomobject]@{path=$rel;reason=$_.Exception.Message;classification='UNPARSEABLE'}}}
# Agent Config sources are instruction prose; do not infer structured permissions.
$surfaces += [pscustomobject]@{name='opencode';structured_sources=@('templates/opencode.v1.json.tmpl','templates/opencode.v2.json.tmpl','source/agents/*.md')}
$surfaces += [pscustomobject]@{name='agent-config';no_structured_declarations=$true;inspected=@('source/global/AGENTS.md','source/adapters/*')}
$grantPath='source/registry/execution-grants.json';try{$g=Get-Content $grantPath -Raw|ConvertFrom-Json;Add-ProtectedFile $grantPath;foreach($x in $g.grants){$permissions += [pscustomobject]@{token=$x;surface='task-kernel';path=$grantPath;declared_by="$grantPath grants[]";enforced_by=$null;enforcement_kind='documented-only';value='grant';tested_by=@()}};foreach($role in $g.role_baselines.PSObject.Properties){foreach($x in $role.Value){$permissions += [pscustomobject]@{token=$x;surface='task-kernel';path=$grantPath;declared_by="$grantPath role_baselines.$($role.Name)[]";enforced_by=$null;enforcement_kind='documented-only';value='baseline';tested_by=@()}}};foreach($category in @('trusted','untrusted')){foreach($x in $g.actor_identity_sources.$category){$permissions += [pscustomobject]@{token=('actor_identity.'+$category+':'+$x);surface='task-kernel';path=$grantPath;declared_by="$grantPath actor_identity_sources.$category[]";enforced_by=$null;enforcement_kind='documented-only';value=$category;tested_by=@()}}}}catch{$unparseable += [pscustomobject]@{path=$grantPath;reason=$_.Exception.Message;classification='UNPARSEABLE'}}
$guardDefs=@(@{name='Get-TaskKernelSensitiveGrants';path='scripts/v3/lib/OrchestrationTaskKernel.ps1'},@{name='Assert-OrchestrationGrantsJson';path='scripts/v3/lib/OrchestrationTaskKernel.ps1'},@{name='Get-OrchestrationEffectiveGrants';path='scripts/v3/lib/OrchestrationTaskKernel.ps1'},@{name='Test-NDGrantProjection';path='scripts/v3/lib/OrchestrationNativeDispatchGrantProjection.ps1'},@{name='Test-NativeDispatchAuthorization';path='scripts/v3/lib/OrchestrationNativeDispatch.ps1'},@{name='Test-OrchestrationAuthorityBoundary';path='scripts/v3/lib/OrchestrationAutonomy.ps1'})
$guards=@();$repoFiles=@(Get-ChildItem scripts,plugins -File -Recurse | Where-Object {$_.FullName -notmatch '\.tests\.ps1$' -and $_.FullName -notmatch 'audit-authority-surfaces\.ps1$'})
foreach($gd in $guardDefs){$lines=[IO.File]::ReadAllLines((Resolve-Path $gd.path));$decl=0;$calls=@();$testCalls=@();for($i=0;$i -lt $lines.Length;$i++){if($lines[$i] -match ('^\s*function\s+'+[regex]::Escape($gd.name)+'\b')){$decl=$i+1}};foreach($f in Get-ChildItem scripts,plugins -File -Recurse){$rel=$f.FullName.Substring($root.Length+1).Replace('\','/');$isTest=$rel -match '\.tests\.ps1$';if($isTest -and $rel -match 'audit-authority-surfaces\.tests\.ps1$'){continue};$n=0;$block=$false;foreach($line in [IO.File]::ReadLines($f.FullName)){$n++;$trim=$line.Trim();if($trim -match '<#|/\*'){$block=$true};if($isTest){if(!$block -and $trim -notmatch '^(#|//|\*|<#)' -and $line.Contains($gd.name)){$testCalls += [pscustomobject]@{path=$rel;line=$n}}}elseif(!$block -and $trim -notmatch '^(#|//|\*|<#)' -and $line.Contains($gd.name) -and -not ($rel -eq $gd.path -and $line -match '^\s*function\s+')){$calls += [pscustomobject]@{path=$rel;line=$n}};if($trim -match '#>|\*/'){$block=$false}}};if(!$decl){$unparseable += [pscustomobject]@{path=$gd.path;anchor=$gd.name;reason='Function anchor missing';classification='UNPARSEABLE'}}else{$guards += [pscustomobject]@{name=$gd.name;path=$gd.path;line=$decl;call_sites=@($calls|Sort-Object path,line -Unique);test_call_sites=@($testCalls|Sort-Object path,line -Unique);invocation_status=if($calls.Count){'called'}elseif($testCalls.Count){'test-only'}else{'uncalled'}};Add-ProtectedFile $gd.path}}
$surfaces += [pscustomobject]@{name='task-kernel';structured_sources=@($grantPath);guards=$guards}
# Map Kernel grants to token-specific code references, guard ranges, and tests.
$sensitive=@('destructive.fs','deploy.production','secrets.read','git.push')
$tokenProofCache=@{}
foreach($p in $permissions|Where-Object surface -eq 'task-kernel'){$token=[string]$p.token;if($tokenProofCache.ContainsKey($token)){$cached=$tokenProofCache[$token];$p.enforced_by=$cached.enforced_by;$p.tested_by=$cached.tested_by;$p.enforcement_kind=$cached.enforcement_kind;continue};$refs=@();$testRefs=@();$guardFound=$false
 foreach($gd in $guardDefs){$src=[IO.File]::ReadAllLines((Resolve-Path $gd.path));$start=0;for($i=0;$i -lt $src.Length;$i++){if($src[$i] -match ('^\s*function\s+'+[regex]::Escape($gd.name)+'\b')){$start=$i+1;break}};if(!$start){continue};$end=$src.Length;for($i=$start;$i -lt $src.Length;$i++){if($src[$i] -match '^\s*function\s+'){ $end=$i;break }};$block=$false;for($i=$start-1;$i -lt $end;$i++){$trim=$src[$i].Trim();if($trim -match '<#|/\*'){$block=$true};if(!$block -and $trim -notmatch '^(#|//|\*|<#)' -and $src[$i].Contains($token)){$refs += "$($gd.path):$($i+1)";$guardFound=$true};if($trim -match '#>|\*/'){$block=$false}}}
 foreach($f in Get-ChildItem scripts,plugins -File -Recurse | Where-Object {$_.FullName -match '\.tests\.ps1$' -and $_.FullName -notmatch 'audit-authority-surfaces\.tests\.ps1$'}){$rel=$f.FullName.Substring($root.Length+1).Replace('\','/');$n=0;$block=$false;foreach($line in [IO.File]::ReadLines($f.FullName)){$n++;$trim=$line.Trim();if($trim -match '<#|/\*'){$block=$true};if(!$block -and $trim -notmatch '^(#|//|\*|<#)' -and $line.Contains($token)){$testRefs += "$rel`:$n"};if($trim -match '#>|\*/'){$block=$false}}}
 $p.tested_by=@($testRefs|Select-Object -Unique)
 if($refs.Count){$p.enforced_by=@($refs|Select-Object -Unique);$p.enforcement_kind=if($guardFound -and $testRefs.Count){'hard'}else{'advisory'}}else{$p.enforced_by=$null;$p.enforcement_kind='documented-only'}
  if(($sensitive -contains $token) -and -not ($p.enforced_by|Where-Object {$_ -match 'OrchestrationTaskKernel\.ps1:85[0-9]'})){$p.enforced_by=$null;$p.enforcement_kind='documented-only'};$tokenProofCache[$token]=[pscustomobject]@{enforced_by=$p.enforced_by;tested_by=$p.tested_by;enforcement_kind=$p.enforcement_kind}
}
# Protect the documented Agent Config instruction sources without interpreting their prose.
foreach($p in @('source/global/AGENTS.md','source/adapters')){if(Test-Path $p){$item=Get-Item $p;if($item.PSIsContainer){$files=Get-ChildItem $p -File -Recurse}else{$files=@($item)};foreach($f in $files){Add-ProtectedFile $f.FullName}}}
# Only compare normalized tokens across distinct surfaces. OpenCode v1/v2 and source/agents form one pipeline.
$byToken=@{};foreach($p in $permissions){if(!$byToken.ContainsKey($p.token)){$byToken[$p.token]=@()};$byToken[$p.token]+=$p.surface};$cross=@();foreach($token in $byToken.Keys){$distinct=@($byToken[$token]|Select-Object -Unique);if($distinct.Count -gt 1){$cross += [pscustomobject]@{token=$token;surfaces=$distinct;rule='Distinct normalized tokens compared by top-level surface; OpenCode templates and source/agents are one pipeline.'}}}
$scanScope=@('templates/opencode.v1.json.tmpl','templates/opencode.v2.json.tmpl','source/agents/*.md','source/global/AGENTS.md','source/adapters/*',$grantPath)+@($guardDefs|ForEach-Object{$_.path}|Select-Object -Unique)
$now=if($GeneratedAt){$GeneratedAt}else{(Get-Date).ToUniversalTime().ToString('o')};$o=[pscustomobject]@{scan_scope=$scanScope;excluded_paths=@('evidence/','docs/','cache/','.git/','node_modules/');surfaces=$surfaces;permissions=$permissions;cross_surface_tokens=$cross;cross_surface_rule='Deduplicate by token within the top-level surface; OpenCode templates plus source/agents are one pipeline; Agent Config prose is not parsed as declarations.';unparseable=$unparseable;protected_files=$protected;method=[pscustomobject]@{mode='structured_json_frontmatter_and_function_anchor_parse';no_model_call=$true;base_revision=$base;generated_by_commit=$base;limitations='Template format must remain JSON; AgentTranslator parser governs frontmatter; static guards/call sites do not prove runtime effects.'};generated_at=$now};$dest=if([IO.Path]::IsPathRooted($OutFile)){$OutFile}else{Join-Path $root $OutFile};New-Item -ItemType Directory -Force (Split-Path $dest)|Out-Null;$o|ConvertTo-Json -Depth 12|Set-Content -Encoding UTF8 $dest
